'use strict';
let KEY='co-chill-v4-browser';
const $=id=>document.getElementById(id),NAMES={k:'Tướng',a:'Sĩ',e:'Tượng',r:'Xe',h:'Mã',c:'Pháo',p:'Tốt'},HAN={K:'帥',A:'仕',E:'相',R:'俥',H:'傌',C:'炮',P:'兵',k:'將',a:'士',e:'象',r:'車',h:'馬',c:'砲',p:'卒'};
const SKILLS={material:'Quan sát và bảo vệ quân',cannon:'Đường Pháo và quân ngòi',horse:'Đường Mã và chân Mã',safety:'An toàn của Tướng'};
const HOW={material:'Kiểm tra an toàn Tướng, tìm nước ăn quân, rồi xem đối thủ có ăn lại được không.',cannon:'Đếm đúng một quân ngòi khi Pháo ăn quân. Kiểm tra lại đường Pháo sau mỗi nước.',horse:'Xác định chân Mã trước khi tính ô đích. Xét cả đường tiến và đường lui.',safety:'Khi bị chiếu, xét di chuyển Tướng, bắt quân chiếu hoặc che đường chiếu hợp lệ.'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'}):'Chưa hẹn';
const btn=(text,action,value='',cls='primary')=>`<button class="${cls}" data-action="${action}" data-value="${esc(value)}">${text}</button>`;
let booting=typeof CoChillCloud!=='undefined';
let publishedPuzzles=[],publishedLoaded=false;
const puzzleBank=()=>FIXTURES.concat(publishedPuzzles);
let state=CC.fresh(),storageOK=true,selected=null,mode='bot',lessonPhase='middle',showMarks=true,replayIndex=0,busy=false,toastTimer;
const PREF_KEY='co-chill-preferences-v1';
let prefs=CC.preferences(),boardFlipped=false,showVariation=false,libraryPage=0,libraryFilter='all',analysisProgress='',audioContext,previousRoute=location.hash||'#home';
try{prefs=CC.preferences(JSON.parse(localStorage.getItem(PREF_KEY)||'null'));}catch{}
try{state=CC.sanitize(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{storageOK=false;}
function save(){if(booting)return;window.CCCloudUI?.save(state);try{localStorage.setItem(KEY,JSON.stringify({...state,preferences:prefs}));}catch{storageOK=false;}if(!storageOK){$('storage-warning').hidden=false;$('storage-warning').textContent='Trình duyệt không lưu được dữ liệu. Phiên này chỉ giữ khi trang còn mở; hãy xuất dữ liệu trước khi đóng.';}}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,7000);}
function go(route){if(location.hash==='#'+route)render();else{internalNavigation=true;location.hash=route;}}
function route(){return(location.hash.slice(1)||'home').split('/');}
function activeGame(){return state.games.find(g=>g.status&&!g.status.over);}
function findPuzzle(id){return puzzleBank().find(p=>p.id===id)||state.games.flatMap(g=>g.moments||[]).find(p=>p.id===id)||(state.session&&state.session.puzzleId===id?state.session.puzzle:null);}
function dueRecords(){return Object.values(state.records).filter(r=>CC.reviewDueAt(r)&&Date.parse(CC.reviewDueAt(r))<=Date.now());}
function completed(){return Object.values(state.records).filter(r=>r.completedAt);}
function heading(title,sub='',back='home'){return `<a class="crumb" href="#${back}">← Quay lại</a><div class="page-top"><div><h1>${title}</h1><p>${sub}</p></div><span class="pill">Bản thử nghiệm</span></div>`;}
function empty(title,copy,link='lessons',cta='Khám phá bài học'){return `<div class="panel empty"><div class="empty-mark">棋</div><h3>${title}</h3><p>${copy}</p><a class="primary" href="#${link}">${cta} →</a></div>`;}
function home(){const due=dueRecords().length,s=state.session,g=activeGame(),ongoing=s&&!['summary','parked'].includes(s.stage);return `<section class="home-intro"><img class="home-cover" src="cover-co-chill.png" alt="Cờ Chill · câu lạc bộ cờ tướng" width="1536" height="1024"><span class="status-dot">Một góc nhỏ để học cờ tướng</span><h1>Chơi một ván.<br><em>Hiểu thêm một chút.</em></h1><p>Chậm lại ở nước đi đáng nhớ. Tự tìm ý tưởng, hiểu lý do và thử sức ở một thế cờ mới.</p></section><div class="next-up"><div><strong>${g?'Ván của bạn đang tiếp tục':due?`${due} hình cờ đã đến lúc ôn`:ongoing?'Bài học của bạn vẫn ở đây':'Bắt đầu bằng một thế cờ nhỏ'}</strong><p>${g?'Quay lại ván; đồng hồ vẫn chạy nếu bạn đã chọn tính giờ.':due?'Ôn một chút, rồi tiếp tục hành trình.':ongoing?'Câu trả lời và bước đang làm đã được giữ lại.':'Khoảng 3–5 phút · Không cần tài khoản'}</p></div>${g?`<a class="primary" href="#game/${g.id}">Tiếp tục ván →</a>`:due?'<a class="primary" href="#review">Ôn hôm nay →</a>':ongoing?btn('Tiếp tục →','resume'):'<a class="primary" href="#howto">Bắt đầu chơi →</a>'}</div><section class="home-grid" aria-label="Bốn khu vực chính"><a class="home-card" href="#play"><span class="tile-symbol">車</span><div><h2>Chơi cờ</h2><p>Một ván với máy, hoặc cùng một người bạn trên thiết bị này.</p><span class="tiny-badge">Máy nhẹ · Hai người</span></div><span class="tile-arrow">↗</span></a><a class="home-card" href="#lessons"><span class="tile-symbol">冊</span><div><h2>Bài học</h2><p>Từ ý tưởng khai cuộc đến cách nhìn một thế cờ.</p><span class="tiny-badge">${puzzleBank().length} hình cờ · 4 kỹ năng</span></div><span class="tile-arrow">↗</span></a><a class="home-card" href="#mistakes"><span class="tile-symbol">↶</span><div><h2>Ván của tôi</h2><p>Trở lại những khoảnh khắc đáng học từ ván của bạn.</p></div><span class="tile-arrow">↗</span></a><a class="home-card" href="#review"><span class="tile-symbol">◷</span><div><h2>Ôn tập</h2><p>Tiếp tục bài đang dở và luyện lại khi đến hẹn.</p><span class="tiny-badge">${due?due+' hình đến hạn':'Theo nhịp của bạn'}</span></div><span class="tile-arrow">↗</span></a></section><div class="home-bottom"><div class="mini-stats"><span><b>${completed().length}</b>hình đã luyện</span><span><b>${state.games.filter(g=>g.status?.over).length}</b>ván đã lưu</span><span><b>${state.summaries.length}</b>lần tự nhìn lại</span></div><p>Không có lời giải trước khi bạn suy nghĩ.<br><a href="#howto">Tìm hiểu cách học ↗</a></p></div>`;}
function boardHTML(pos,{interactive=false,chosen=null,last=null,mark=null}={}){
 let lines='';for(let y=0;y<10;y++)lines+=`<line x1="25" y1="${25+50*y}" x2="425" y2="${25+50*y}"/>`;
 for(let x=0;x<9;x++){const xx=25+50*x;lines+=`<line x1="${xx}" y1="25" x2="${xx}" y2="225"/><line x1="${xx}" y1="275" x2="${xx}" y2="475"/>`;}
 lines+='<path d="M25 225V275M425 225V275M175 25L275 125M275 25L175 125M175 375L275 475M275 375L175 475"/>';
 const screen=i=>boardFlipped?89-i:i;
 const checked=pos.inCheck();
 let html=`<div class="board-shell"><div class="board" role="group" aria-label="Bàn cờ tướng"><svg class="board-lines" viewBox="0 0 450 500" aria-hidden="true"><g stroke="currentColor" stroke-width="1.3" fill="none">${lines}</g><text x="132" y="257" text-anchor="middle" fill="currentColor" font-family="serif" font-size="19">楚 河</text><text x="322" y="257" text-anchor="middle" fill="currentColor" font-family="serif" font-size="19">漢 界</text></svg>`;
 pos.board.forEach((piece,i)=>{const sq=XQ.square(i),j=screen(i),name=piece==='.'?'Ô trống':NAMES[piece.toLowerCase()]+' '+(XQ.side(piece)==='w'?'Đỏ':'Đen');
 html+=`<button type="button" class="board-square${chosen===sq?' selected':''}${last?.slice(0,2)===sq?' last-from':''}${last?.slice(2)===sq?' last-to':''}${checked&&piece.toLowerCase()==='k'&&XQ.side(piece)===pos.turn?' checked':''}" style="left:${(j%9+.5)/9*100}%;top:${(Math.floor(j/9)+.5)/10*100}%" data-square="${sq}" aria-label="${sq} · ${name}" ${interactive?'':'disabled'}>${piece==='.'?'':`<span class="piece${XQ.side(piece)==='w'?' red':''}${prefs.pieces==='vi'?' vietnamese':''}">${prefs.pieces==='vi'?NAMES[piece.toLowerCase()]:HAN[piece]}</span>`}</button>`;});
 if(mark&&showMarks){const a=screen(XQ.index(mark.slice(0,2))),b=screen(XQ.index(mark.slice(2)));html+=`<svg class="board-overlay" viewBox="0 0 450 500" aria-hidden="true"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="5" refY="3.5" orient="auto"><path d="M0 0L7 3.5L0 7" fill="#2a705d"/></marker></defs><circle cx="${25+(a%9)*50}" cy="${25+Math.floor(a/9)*50}" r="22" fill="none" stroke="#2a705d" stroke-width="3"/><path d="M${25+(a%9)*50} ${25+Math.floor(a/9)*50}L${25+(b%9)*50} ${25+Math.floor(b/9)*50}" fill="none" stroke="#2a705d" stroke-width="4" marker-end="url(#arrow)"/></svg>`;}
 return html+`</div><div class="board-caption"><span>${boardFlipped?'Đen':'Đỏ'} ở dưới</span><span>Bấm lại quân đang chọn để bỏ chọn</span></div></div><div class="board-tools">${btn('⇅ Lật bàn','flip-board','','quiet')}${btn(prefs.pieces==='han'?'Chữ Việt':'Chữ Hán','toggle-pieces','','quiet')}</div>`;
}
function beginPuzzle(p,{related=false,source='lesson',force=false}={}){if(!p)return toast('Không tìm thấy bài.');if(p.id.startsWith('custom-')&&state.session?.puzzleId===p.id&&state.session.puzzle?.version!==p.version){if(!confirm('Bài đã có phiên bản mới. Xuất bản nháp hiện tại ra file rồi bắt đầu lại với nội dung mới?'))return;download('co-chill-nhap-truoc-cap-nhat.json',JSON.stringify(CC.safeExport(state),null,2));}if(activeGame())return toast('Hãy kết thúc ván đang chơi trước khi mở hướng dẫn.');if(!force&&state.session&&!['summary','parked'].includes(state.session.stage)&&state.session.puzzleId!==p.id&&!confirm('Bạn đang có một bài dở. Bắt đầu bài mới sẽ thay chỗ tiếp tục hiện tại; kết quả đã hoàn thành vẫn giữ.'))return;const firstExposure=!state.records[p.id]?.seenCount;state=CC.markSeen(state,p);state.session=CC.createSession(p,{source,related,firstExposure});selected=null;showVariation=false;save();go('learn');}
window.CCBasicPuzzles=skill=>FIXTURES.filter(p=>p.skill===skill).map(p=>({id:p.id,title:p.title,goal:p.goal,skill:p.skill}));
window.CCRecommendBasicPuzzle=(skill,excludeId)=>CC.recommend(puzzleBank(),state.records,skill,excludeId)?.puzzle||null;
window.CCStartBasicPuzzle=(id,related=false)=>{const puzzle=FIXTURES.find(p=>p.id===id);if(!puzzle)return false;const previous=state.session;beginPuzzle(puzzle,{related,source:related?'related':'lesson'});return state.session!==previous&&state.session?.puzzleId===id;};
function currentPuzzle(){return findPuzzle(state.session?.puzzleId);}
function accepted(p,move){return !!move&&(move===p.solution||(p.alternatives||[]).includes(move));}
function learn(){
 const session=state.session,p=currentPuzzle();if(p?.id?.startsWith('custom-')&&session?.puzzle?.version!==p.version)return empty('Bài có nội dung mới','Bản nháp cũ được giữ và tạm dừng chấm. Chọn lại bài trong thư viện để xuất nháp rồi bắt đầu phiên bản mới.','lessons','Mở thư viện');if(p?.id?.startsWith('custom-')&&publishedLoaded&&!publishedPuzzles.some(x=>x.id===p.id))return empty('Bài đang được kiểm tra lại','Nháp được giữ; bài tạm dừng chấm cho đến khi chủ website duyệt lại.','lessons','Chọn bài khác');if(!session||!p)return empty('Chọn một hình cờ để bắt đầu','Mỗi bài đều bắt đầu bằng suy nghĩ của bạn.');
 if(activeGame())return empty('Ván cờ vẫn đang diễn ra','Hướng dẫn được mở sau khi ván kết thúc.','game/'+activeGame().id,'Quay lại ván');
 const pos=XQ.Position.fromFen(p.fen),after=['explain','retry','complete','summary'].includes(session.stage);let right='';
 if(session.stage==='parked'){right=`<p class="eyebrow">CẦN HỌC TIẾP</p><h2>Mình quay lại hình này sau nhé.</h2><p>Ba lượt suy nghĩ đã được giữ. Đây chưa phải bài đã hoàn thành; ngày mai bạn có thể thử lại từ phần đang cần hiểu.</p><div class="button-row"><a class="primary" href="#lessons">Chọn một bài khác</a><a class="secondary" href="#review">Xem lịch học tiếp</a></div>`;}else if(session.stage==='related_pending'){
 const q=findPuzzle(session.pendingPuzzleId);right=`<p class="eyebrow">VẬN DỤNG</p><h2>Thử thêm một bài nữa.</h2><p>Phần vừa học đã được ghi lại. Hãy thử tự quan sát hình tiếp theo.</p><p class="subtle">${q&&state.records[q.id]?.seenCount?'Bài đã gặp. Kho bài hiện còn nhỏ.':'Bài chưa gặp trên trình duyệt này.'}</p>${btn('Bắt đầu bài tiếp theo →','related-start')}${btn('Để lần sau','pause','','quiet')}<p class="subtle">Bạn sẽ quay lại đúng bước này; bài tiếp theo chưa được tính là đã làm.</p>`;
 }else if(session.stage==='reflect'){
 const wait=0;
 right=`<p class="eyebrow">TỰ QUAN SÁT · ${session.submissionCount?`LƯỢT ${Math.min(3,session.submissionCount+1)}/3`:'TRƯỚC LỜI GIẢI'}</p><h2>${prefs.tone==='friendly'?'Mình cùng nhìn thế cờ nhé.':'Bạn nhìn thế cờ thế nào?'}</h2><p class="subtle">Nêu ý ngắn, rồi chọn một nước trên bàn. Bản thử kiểm tra nước đi; chưa tự chấm hiểu biết qua câu chữ.</p>${session.coachFeedback?`<p class="notice">${esc(session.coachFeedback)}</p>`:''}<form id="reflection-form">${CC.PROMPTS.map((q,i)=>`<label class="field"><span class="question-label"><i>0${i+1}</i> ${q}</span><textarea data-answer="${i}" rows="2" maxlength="1500" aria-describedby="hint-${i}" placeholder="Suy nghĩ của bạn…">${esc(session.answers[i])}</textarea><span id="hint-${i}" class="question-hint">${session.helpLevel||prefs.level==='new'?CC.HINTS[i]:''}</span></label>`).join('')}<div class="candidate" id="candidate">${session.candidate?'Nước bạn chọn: '+esc(CC.notateMove(pos,session.candidate)):'Chọn quân, rồi chọn ô đến để đề xuất một nước.'}</div><div class="button-row"><button class="primary" type="submit">Gửi suy nghĩ →</button></div></form>${btn('Tôi chưa biết · giúp tôi quan sát','unknown','','quiet')}${session.helpLevel?`<div class="question-hint"><p>Hãy dành một chút thời gian quan sát theo các gợi ý trên. Bạn có thể gửi câu trả lời bất cứ lúc nào.</p><button class="secondary" data-action="guided-reveal" id="guided-reveal" ${wait?'disabled':''}>${wait?`Quan sát thêm ${wait} giây`:'Vẫn chưa tìm ra · xem hướng dẫn'}</button><p class="subtle">Xem hướng dẫn được ghi là có hỗ trợ và cần ôn lại.</p></div>`:''}`;
 }else if(session.stage==='retry'){
 right=`<p class="eyebrow">LUYỆN LẠI · SAU HƯỚNG DẪN</p><h2>Thử lại ý tưởng vừa học.</h2><p>Chọn quân và ô đến. Bạn còn ${Math.max(0,3-(session.retryCount||0))} lượt thử trong phiên này.</p>${btn('Quay về giải thích','explain','','secondary')}<p class="subtle">Thử lại sau lời giải không được tính thành tự giải lần đầu.</p>`;
 }else{
 const assisted=session.assisted||!accepted(p,session.candidate);
 right=`<p class="eyebrow">ĐỐI CHIẾU SUY NGHĨ</p><h2>Ý tưởng cần giữ lại.</h2><p class="notice">${assisted?'Lượt này có hỗ trợ hoặc cần luyện thêm. Sau đây là một phương án để bạn đối chiếu.':'Nước đề xuất phù hợp mục tiêu mẫu. Hãy đối chiếu cả lý do; hệ thống chưa tự xác nhận câu trả lời tự do đúng hoàn toàn.'}</p><div class="explanation-section"><h4>Thế cờ thay đổi như thế nào?</h4><p>${esc(p.what)}</p></div><div class="explanation-section"><h4>Điều gì làm nên ý tưởng này?</h4><p>${esc(p.why)}</p></div><div class="explanation-section"><h4>Lần tới bạn nên kiểm tra điều gì?</h4><p>${esc(p.how||HOW[p.skill])}</p></div><div class="button-row">${btn(showVariation?'↶ Trở về thế ban đầu':'Xem nước minh họa trên bàn','variation','','secondary')}${btn('Thử lại vị trí này','retry','','secondary')}</div><details class="separation"><summary>Chi tiết hơn · suy nghĩ và căn cứ</summary><p>Nước minh họa: ${esc(CC.notateMove(pos,p.solution))}. Có thể có nhiều phương án hợp lý.</p>${(session.firstAnswers||session.answers).map((a,i)=>`<p><b>Suy nghĩ ban đầu ${i+1}:</b> ${esc(a||'Chưa biết')}</p>`).join('')}<p>Lời giải theo mẫu hoặc nội dung đã duyệt, dựa trên nước hợp lệ. ${p.engine?esc(p.engine.name)+' · độ sâu ghi nhận '+p.engine.depth+' nửa nước.':''} Chưa có AI chấm lập luận. Không dùng điểm này làm xếp hạng.</p></details><div class="button-row">${btn(session.related?'Lưu lượt học & tự nhìn lại →':assisted?'Lưu lượt học & đưa vào ôn tập →':'Lưu lượt học & làm bài tiếp →','finish')}</div><p class="subtle">Lịch ôn tính từ lúc bạn kết thúc hình này. Hoàn thành lượt luyện chưa phải chứng nhận đã hiểu.</p>`;
 }
 const title=p.gameId?'Vị trí cần xem lại':session.related?'Thử sức ở thế cờ mới':'Quan sát và đưa ra ý tưởng';
 const shown=after&&session.stage!=='retry'&&showVariation?pos.play(p.solution):pos;
 return `${heading(title,'Tự suy nghĩ trước, rồi đối chiếu với lời giải.','lessons')}<div class="learn-grid"><div class="board-panel"><div class="board-meta"><span class="player-pill"><i class="player-dot ${pos.turn==='b'?'black':''}"></i>${pos.turn==='w'?'Đỏ':'Đen'} đến lượt</span><span class="pill">${after?'Đang đối chiếu':'Chưa mở lời giải'}</span></div>${boardHTML(shown,{interactive:['reflect','retry'].includes(session.stage),chosen:selected,mark:after&&session.stage!=='retry'&&!showVariation?p.solution:null,last:showVariation?p.solution:null})}<p id="move-feedback" class="feedback" role="status"></p><p class="subtle">${p.gameId?'Từ ván của bạn · đối chiếu với giới hạn của lượt tìm kiếm.':p.status==='published'?'Bài do chủ website biên tập và duyệt · '+esc(p.source):'Bài tự dựng · chưa được chuyên gia duyệt sư phạm.'}</p>${btn('Lưu chỗ này · về trang chủ','pause','','quiet')}<a class="quiet" href="#rules">Xem luật đi quân</a></div><section class="panel learning-panel"><div class="stepper"><span class="active"></span><span class="${after?'active':''}"></span><span></span></div>${right}<p id="learn-feedback" class="feedback" role="status"></p><small id="draft-status">Nháp được giữ trên máy; trạng thái đồng bộ ở đầu trang.</small><details class="separation"><summary>Báo vấn đề về hình này</summary>${window.CCCloudUI?.feedbackForm('#learn/'+p.id)||''}</details></section></div>`;
}
function finish(){const s=state.session,p=currentPuzzle();state=CC.finishPuzzle(state,s,p,{success:accepted(p,s.candidate),assisted:s.assisted});save();if(state.session.stage==='parked'){render();return;}if(s.related)go('summary');else nextRelated();}
function nextRelated(){const s=state.session,p=currentPuzzle(),r=CC.recommend(puzzleBank(),state.records,p.skill,p.id);if(!r)return go('summary');state.session={...s,stage:'related_pending',pendingPuzzleId:r.puzzle.id};save();render();}
function lessons(){const opening=lessonPhase==='opening';return `${heading('Bài học','Học một ý tưởng, rồi đặt nó vào một thế cờ cụ thể.')}<div class="filters">${[['opening','Khai cuộc'],['middle','Trung cuộc'],['end','Tàn cuộc']].map(([v,t])=>btn(t,'phase',v,lessonPhase===v?'active':'')).join('')}</div>${opening?`<p class="notice">Bốn minh họa nước mở đầu. Đây chưa phải giáo trình khai cuộc hoặc thư viện biến đầy đủ.</p><div class="list">${OPENINGS.map((p,i)=>`<div class="list-row"><div class="row-main"><span class="mini-icon">${p.icon}</span><div><h3>${p.title}</h3><p>${p.short}</p></div></div>${btn('Xem hướng dẫn →','opening',String(i),'secondary')}</div>`).join('')}</div>`:`<p class="notice">${lessonPhase==='end'?'12 thế ít quân với mục tiêu ngắn; chưa có bộ tàn cuộc chuẩn hoặc yêu cầu đánh đến hết ván.':'Luyện bốn kỹ năng thường cần khi phân tích trung cuộc. Các hình mẫu đã giản lược quân, không phải ván trung cuộc đầy đủ.'}</p><div class="grid-2">${Object.entries(SKILLS).map(([k,n])=>`<section class="panel"><p class="eyebrow">${puzzleBank().filter(p=>p.skill===k).length} HÌNH MẪU</p><h3>${n}</h3><p class="subtle">${HOW[k]}</p><div class="list">${puzzleBank().filter(p=>p.skill===k).map(p=>`<div class="list-row"><div><h3>${esc(p.title)}</h3><p>${state.records[p.id]?.pendingReview?'Cần học tiếp':state.records[p.id]?.completedAt?(state.records[p.id].assisted?'Đã luyện có hỗ trợ · ':'Đã luyện · ')+date(state.records[p.id].completedAt):state.records[p.id]?.seenCount?'Đã mở · có thể luyện lại':'Chưa gặp trên thiết bị này'}</p></div>${btn('Luyện','start',p.id,'secondary')}</div>`).join('')}</div></section>`).join('')}</div>`}`;}
const OPENINGS=[{title:'Pháo đầu',icon:'炮',short:'Quan sát Pháo trên lộ giữa',move:'h2e2',text:'Pháo từ h2 sang e2, đi ngang trên đường không bị cản. Đây là cách đưa Pháo vào lộ giữa. Tiếp theo vẫn cần phát triển quân và kiểm tra phản ứng đối thủ; không có một chuỗi nước bắt buộc cho mọi ván.'},{title:'Phi tượng',icon:'相',short:'Nhìn cách Tượng phối hợp phòng thủ',move:'g0e2',text:'Tượng từ g0 lên e2; mắt Tượng f1 phải trống. Tượng hoạt động ở bên mình và không qua sông. Một nước phát triển Tượng chưa đủ để khẳng định bên nào hơn.'},{title:'Tiên nhân chỉ lộ',icon:'兵',short:'Quan sát nước tiến Tốt mở đầu',move:'c3c4',text:'Tốt từ c3 tiến lên c4. Khi chưa qua sông, Tốt chỉ đi thẳng một ô. Hãy quan sát những đường quân khác có thể hoạt động sau khi Tốt tiến.'},{title:'Sĩ giác pháo',icon:'炮',short:'Một cách bố trí Pháo khác',move:'h2f2',text:'Pháo từ h2 sang f2, không cần quân ngòi khi không ăn quân. Tên khai cuộc chỉ mô tả cách bố trí ban đầu; kế hoạch tiếp theo phụ thuộc nước đáp của đối thủ.'}];
function opening(i){const p=OPENINGS[i]||OPENINGS[0],pos=XQ.Position.fromFen(XQ.START_FEN),after=replayIndex>0?pos.play(p.move):pos;return `${heading(p.title,'Minh họa khai cuộc · đã xem không đồng nghĩa đã hiểu','lessons')}<div class="learn-grid"><div class="board-panel">${boardHTML(after,{last:replayIndex?p.move:null})}<div class="button-row">${btn('← Thế ban đầu','opening-before',i,'secondary')}${btn('Xem nước đi →','opening-after',i,'secondary')}</div></div><div class="panel"><p class="eyebrow">HƯỚNG DẪN NGẮN</p><h2>${p.short}</h2><p>${p.text}</p><p class="notice">Nước minh họa được kiểm tra bằng bộ luật. Chưa có câu hỏi và chấm hiểu biết cho phần khai cuộc này.</p><a class="primary" href="#lessons">Trở lại bài học →</a></div></div>`;}
function playSetup(){const g=activeGame();return `${heading('Chọn một ván cờ','Chơi tập trung, rồi cùng nhìn lại sau ván.')}<div class="grid-3">${[['bot','車','Chơi với máy','Máy nhẹ trên thiết bị · chưa có Elo'],['local','棋','Hai người một máy','Luân phiên cầm Đỏ và Đen'],['online','↗','Chơi trực tuyến','Sẽ phát triển sau vòng học cốt lõi']].map(([id,ic,t,d])=>`<button class="mode-card ${mode===id?'active':''}" data-action="mode" data-value="${id}" ${id==='online'?'disabled':''}><span class="mode-icon">${ic}</span><b>${t}</b><span>${d}</span></button>`).join('')}</div><div class="grid-2 separation"><section class="panel"><h3>Thiết lập trước khi chơi</h3>${g?`<p class="notice">Mỗi lần chỉ có một ván. Đồng hồ vẫn chạy khi bạn rời trang.</p><a class="primary" href="#game/${g.id}">Tiếp tục ván đang chơi →</a>`:`<form id="new-game-form"><label class="field"><span>Bên bạn cầm</span><select name="color"><option value="w">Đỏ · đi trước</option><option value="b">Đen · đi sau</option><option value="random">Ngẫu nhiên</option></select></label><label class="field"><span>Thời gian mỗi bên và giây cộng sau mỗi nước</span><select name="time"><option value="600+5">10 phút + 5 giây</option><option value="300+3">5 phút + 3 giây</option><option value="180+2">3 phút + 2 giây</option><option value="0+0">Không giới hạn thời gian</option></select></label>${mode==='bot'?'<label class="field"><span>Mức tìm kiếm cơ bản</span><select name="depth"><option value="1">Nhanh · 1 nửa nước</option><option value="2">Kỹ hơn · tối đa 2 nửa nước</option></select></label><label class="field"><span>Bộ tính nước</span><select name="engine"><option value="local">Cơ bản · chạy trên thiết bị</option><option value="server">Máy chủ · cần tài khoản, tùy engine đã cài</option></select></label>':''}<button class="primary full" type="submit">Bắt đầu chơi →</button></form>`}<p class="subtle separation">Không gợi nước hoặc xem lại lịch sử bàn cờ khi ván đang chạy. <a href="#rules">Xem phạm vi bộ luật</a>.</p></section><section class="panel"><h3>Nhập ván để xem lại</h3><p class="subtle">Dán ký phổ Việt hoặc nước tọa độ. Hệ thống dừng tại nước lỗi và không lưu ván dở do nhập lỗi. Chưa nhận dạng ảnh.</p><form id="import-form"><label class="field"><span>FEN đầu ván · để trống để dùng thế xuất phát</span><textarea name="fen" rows="2" maxlength="200" placeholder="Để trống nếu bắt đầu từ thế xuất phát"></textarea></label><label class="field"><span>Biên bản</span><textarea name="moves" rows="4" maxlength="10000" placeholder="P2-5 M8.7 hoặc h2e2 h9g7"></textarea></label><label class="field"><span>Hoặc mở file văn bản .txt</span><input type="file" id="notation-file" accept=".txt,text/plain"></label><label class="field"><span>Bên cần xem lại</span><select name="reviewSide"><option value="w">Đỏ</option><option value="b">Đen</option></select></label><label class="check-line"><input type="checkbox" name="completeRecord" required><span>Tôi đã nhập toàn bộ biên bản từ đầu đến cuối (kết quả có thể do đầu hàng/thỏa thuận).</span></label><button class="secondary" type="submit">Kiểm tra & mở ván</button><p id="import-feedback" class="feedback" role="status"></p></form></section></div>`;}
function gameList(){const source=libraryFilter==='archive'?state.games.slice(0,-200):libraryFilter==='favorite'?state.games:state.games.slice(-200);const filtered=source.slice().reverse().filter(g=>libraryFilter==='archive'||libraryFilter==='all'||libraryFilter==='favorite'&&g.favorite||libraryFilter==='unreviewed'&&!g.moments||libraryFilter==='reviewed'&&g.moments);const pages=Math.ceil(filtered.length/20);libraryPage=Math.min(libraryPage,Math.max(0,pages-1));return `<div class="filters">${[['all','Tất cả'],['unreviewed','Chưa xem lại'],['reviewed','Đã phân tích'],['favorite','Yêu thích'],['archive','Kho lưu trữ']].map(([k,v])=>btn(v,'library-filter',k,k===libraryFilter?'active':'')).join('')}</div><div class="list">${filtered.slice(libraryPage*20,libraryPage*20+20).map(g=>`<div class="list-row"><div><h3>${esc(g.title)}</h3><p>${date(g.createdAt)} · ${g.player==='b'?'Cầm Đen':'Cầm Đỏ'} · ${g.moves?.length||0} nửa nước</p><p>${esc(g.status?.reason||'Đang chơi')} · ${g.moments?'Đã phân tích':'Chưa phân tích'}</p></div><div class="button-row">${btn(g.favorite?'★':'☆','favorite',g.id,'quiet')}<a class="secondary" href="#${g.status?.over?'moments':'game'}/${g.id}">${g.status?.over?'Xem lại':'Tiếp tục'} →</a></div></div>`).join('')||'<p>Chưa có ván phù hợp bộ lọc.</p>'}</div>${pages>1?`<div class="button-row">${btn('Trang trước','library-prev','','secondary')}<span>${libraryPage+1} / ${pages}</span>${btn('Trang sau','library-next','','secondary')}</div>`:''}`;}
function newGame({fen=XQ.START_FEN,moves=[],imported=false,color='w',seconds=0,increment=0,depth=1,engineChoice='local'}={}){
 if(activeGame())return toast('Kết thúc ván đang chơi trước khi tạo ván khác.');if(engineChoice==='server'&&!window.CCCloudUI?.sessionUser())return toast('Đăng nhập để dùng máy chủ, hoặc chọn máy cơ bản trên thiết bị.');
 let pos=XQ.Position.fromFen(fen),history=[];fen=pos.fen();
 if(imported){const duplicate=state.games.find(g=>g.initialFen===fen&&JSON.stringify(g.moves.map(m=>m.move))===JSON.stringify(moves));if(duplicate){go('moments/'+duplicate.id);return toast('Đã mở biên bản có sẵn; không tạo bản trùng.');}}
 for(const move of moves){const next=pos.play(move);history.push({move,before:pos.fen(),after:next.fen(),side:pos.turn});pos=next;}
 if(color==='random')color=Math.random()<.5?'w':'b';
 const g={id:'g'+Date.now(),title:imported?'Ván / thế cờ đã nhập':mode==='bot'?'Ván với máy':'Ván hai người một máy',createdAt:Date.now(),mode:imported?'import':mode,player:color,depth,engineChoice,initialFen:fen,fen:pos.fen(),moves:history,status:imported?{over:true,winner:null,reason:'Đã nhập để học'}:pos.status(),clock:{w:seconds*1000,b:seconds*1000,last:Date.now(),enabled:seconds>0,increment:increment*1000},invalidMoves:[]};
 state.games.push(g);/* Older games remain available in the archive; never silently truncate. */save();selected=null;boardFlipped=color==='b';go((imported?'moments/':'game/')+g.id);if(!imported)maybeBot(g);
}
function notationTable(g,clickable=false){const rows=CC.pairMoveHistory(g.initialFen,g.moves.map(m=>m.move));return `<div class="notation-scroll"><table class="notation-table"><thead><tr><th>Nước</th><th>Đỏ</th><th>Đen</th></tr></thead><tbody>${rows.slice(clickable?0:-10).map(row=>`<tr><td>${row.number}</td>${['red','black'].map(side=>`<td>${row[side]?clickable?btn(esc(row[side].notation),'replay-jump',String(row[side].ply+1),'quiet'):esc(row[side].notation):'—'}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="3">Chưa có nước đi</td></tr>'}</tbody></table></div>`;}
function captures(g){const lost={w:[],b:[]};for(const m of g.moves){const before=XQ.Position.fromFen(m.before),piece=before.board[XQ.index(m.move.slice(2))];if(piece!=='.')lost[XQ.side(piece)].push(piece);}return `<div class="captures"><p>Đỏ đã mất: ${lost.w.map(p=>prefs.pieces==='vi'?NAMES[p.toLowerCase()]:HAN[p]).join(' · ')||'—'}</p><p>Đen đã mất: ${lost.b.map(p=>prefs.pieces==='vi'?NAMES[p.toLowerCase()]:HAN[p]).join(' · ')||'—'}</p></div>`;}
function gameView(g){
 if(!g)return empty('Không tìm thấy ván','Bạn có thể bắt đầu một ván mới.','play','Chơi cờ');
 const pos=XQ.Position.fromFen(g.fen),last=g.moves.at(-1)?.move,top=boardFlipped?'w':'b',bottom=XQ.other(top),player=color=>`<span class="player-pill"><i class="player-dot ${color==='b'?'black':''}"></i>${color==='w'?'Đỏ':'Đen'}</span><span id="clock-${color}" class="clock ${pos.turn===color?'active':''}">${clockText(g,color)}</span>`;
 return `${heading(g.title,'Tập trung vào ván cờ. Phần học mở sau khi kết thúc.','play')}<div class="learn-grid"><div class="board-panel"><div class="board-meta">${player(top)}</div>${boardHTML(pos,{interactive:!g.status.over&&!busy&&(g.mode==='local'||pos.turn===g.player),chosen:selected,last})}<div class="board-meta">${player(bottom)}</div><p id="game-feedback" class="feedback" role="status"></p>${captures(g)}</div><div class="panel game-panel">${g.technicalPause?`<p class="notice">Máy gặp sự cố. Đồng hồ tạm dừng; ván chưa bị tính thua. ${esc(g.engineError||'')}</p><div class="button-row">${btn('Thử máy lại','retry-bot',g.id,'secondary')}${btn('Kết thúc do kỹ thuật','technical-end',g.id,'quiet')}</div>`:''}${g.status.over?`<div class="game-result"><h2>${g.status.winner?(g.status.winner==='w'?'Đỏ':'Đen')+' thắng':g.status.needsVerification?'Cần kiểm chứng phán quyết':'Ván đã kết thúc'}</h2><p>${esc(g.status.reason)}</p><a class="primary" href="#moments/${g.id}">Xem lại ván này →</a><div class="button-row">${btn('Chơi ván tiếp','rematch',g.id,'secondary')}</div></div>`:`<p class="eyebrow">${busy?'MÁY ĐANG TÍNH NƯỚC':'VÁN ĐANG DIỄN RA'}</p><h2>${pos.turn==='w'?'Đỏ':'Đen'} đến lượt${pos.inCheck()?' · bị chiếu':''}</h2><p class="subtle">${g.mode==='bot'?(g.engineLabel||'Máy cơ bản · chưa xếp hạng'):'Hai người thao tác trên cùng thiết bị.'}</p>`}${g.drawOffer&&!g.status.over&&g.drawOffer.expiresAt>Date.now()?`<div class="notice"><p>${g.drawOffer.from==='w'?'Đỏ':'Đen'} đề nghị hòa. Bên còn lại xác nhận trong 15 giây; đồng hồ vẫn chạy.</p>${btn('Đồng ý hòa','draw-accept',g.id,'secondary')}${btn('Từ chối','draw-decline',g.id,'quiet')}</div>`:''}<h3>Biên bản</h3>${notationTable(g)}${!g.status.over?`<div class="button-row">${btn('Xin thua','resign',g.id,'secondary')}${g.mode==='local'?btn('Thỏa thuận hòa','draw',g.id,'quiet'):''}</div>`:''}<details class="separation"><summary>Luật và giới hạn</summary><p>Không đi lại nước và không mở phân tích trong ván. Những chuỗi lặp cần phân xử ngoài phạm vi đã kiểm chứng sẽ dừng để xác minh, không tự gán thắng hoặc hòa.</p><a href="#rules">Đọc phạm vi bộ luật</a></details></div></div>`;
}
function clockText(g,color){if(g.technicalPause)return 'Tạm dừng';if(!g.clock?.enabled)return '∞';let ms=g.clock[color];if(!g.status.over&&XQ.Position.fromFen(g.fen).turn===color)ms-=Date.now()-g.clock.last;ms=Math.max(0,ms);return Math.floor(ms/60000)+':'+String(Math.floor(ms/1000)%60).padStart(2,'0');}
function tickGame(g){if(!g||g.status.over||g.technicalPause||!g.clock?.enabled)return false;const pos=XQ.Position.fromFen(g.fen);if(g.clock[pos.turn]-(Date.now()-g.clock.last)<=0){g.clock[pos.turn]=0;g.status={over:true,winner:XQ.other(pos.turn),reason:'Hết thời gian'};save();return true;}return false;}
function moveGame(g,move){if(tickGame(g)||g.status.over)return render();const pos=XQ.Position.fromFen(g.fen),next=pos.play(move),captured=pos.board[XQ.index(move.slice(2))]!=='.';const clock=CC.applyClockMove(g.clock,pos.turn,Date.now());if(clock.expired){tickGame(g);return render();}g.clock=clock.clock;g.moves.push({move,before:pos.fen(),after:next.fen(),side:pos.turn});g.fen=next.fen();g.status=next.status();if(!g.status.over){const repetition=CC.repetitionStatus(g.initialFen,g.moves.map(m=>m.move));if(repetition.over||repetition.needsVerification)g.status={...repetition,over:true};}if(!g.status.over&&g.moves.length>=200)g.status={over:true,winner:null,reason:'Giới hạn 200 nửa nước của bản thử · không tính hòa',needsVerification:true};selected=null;playSound(next.inCheck()?'check':captured?'capture':'move');save();render();maybeBot(g);}
async function maybeBot(g){
 if(busy||!g||g.mode!=='bot'||g.status.over||XQ.Position.fromFen(g.fen).turn===g.player)return;
 busy=true; if(route()[0]==='game')render();
 const initialFen=g.fen, started=Date.now();
 try{
   if(tickGame(g)||g.status.over)return;
   const pos=XQ.Position.fromFen(g.fen);let move;
   if(g.engineChoice==='server'){
     const cloud=window.CCCloudUI?.snapshot();
     if(!cloud?.client.session.authenticated)throw new Error('Cần đăng nhập để dùng máy chủ. Chọn máy cơ bản để chơi không cần tài khoản.');
     if(cloud.client.pending&&!await cloud.client.flush())throw new Error('Chưa đồng bộ được ván.');
     const a=CoChillEngine.requireStrong(await cloud.client.request('/api/engine/analyze',{method:'POST',body:{purpose:'bot',gameId:g.id,fen:g.fen,mode:'quick',requireStrong:true}}));
     move=a.best_move;g.engineLabel=a.engine_name||'Engine máy chủ';
   }else{
     await new Promise(r=>setTimeout(r,50));
     const a=XQ.analyze(pos,{depth:g.depth,maxMs:g.depth===2?550:180});move=a.bestMove;g.engineLabel='Máy cơ bản · '+a.depth+' nửa nước';
   }
   if(g.fen!==initialFen||g.status.over||!state.games.includes(g))return;
   if(!pos.legalMoves().includes(move))throw new Error('Máy chưa trả được nước hợp lệ.');
   busy=false;moveGame(g,move);
 }catch(error){
   // Server failures never become a human timeout. Keep the board and mark a technical pause.
   if(state.games.includes(g)&&!g.status.over){g.technicalPause=true;g.clock.last=Date.now();g.engineError=error.message;save();toast('Đã tạm dừng ván do máy chưa trả nước. Có thể thử lại hoặc kết thúc với nhãn sự cố kỹ thuật.');}
 }finally{busy=false;if(route()[0]==='game')render();}
}
function inferSkill(pos,move){if(pos.inCheck())return 'safety';return({c:'cannon',h:'horse'})[pos.board[XQ.index(move.slice(0,2))].toLowerCase()]||'material';}
async function analyzeGame(g,analysisMode='quick'){
 if(!g||!g.status.over||busy||activeGame())return;
 const task={controller:new AbortController(),route:location.hash};analysisTask=task;busy=true;analysisProgress='Đang chuẩn bị phân tích…';render();
 try{
   const cloud=window.CCCloudUI?.snapshot(),remote=!!cloud?.client.session.authenticated;
   if(!remote&&prefs.level==='intermediate')throw new Error('Phân tích ở mức đã biết chơi cần tài khoản và Pikafish trên máy chủ. Biên bản vẫn được giữ; bạn có thể luyện bài đã kiểm chứng trong Bài học.');
   if(remote&&cloud.client.pending&&!await cloud.client.flush())throw new Error('Chưa đồng bộ được ván. Mở Tài khoản để xử lý trước khi phân tích.');
   const turns=g.moves.map((m,i)=>({...m,ply:i})).filter(m=>g.mode==='local'||m.side===g.player).slice(-20),found=[];
   let fallback=false,engineName='Máy cơ bản trên thiết bị';
   for(let n=0;n<turns.length;n++){
     if(analysisTask!==task||task.controller.signal.aborted)return;
     analysisProgress=`Đang kiểm tra vị trí ${n+1} / ${turns.length}`;
     if($('analysis-progress'))$('analysis-progress').textContent=analysisProgress;
     const m=turns[n],pos=XQ.Position.fromFen(m.before);
     const raw=remote?CoChillEngine.requireStrong(await cloud.client.request('/api/engine/analyze',{method:'POST',signal:task.controller.signal,body:{purpose:'review-scan',gameId:g.id,fen:g.initialFen,moves:g.moves.slice(0,m.ply).map(x=>x.move),selectedMove:m.move,mode:analysisMode,requireStrong:true}})):CoChillEngine.local(pos,m.move,XQ.analyze);
     const a=CoChillEngine.validate(pos,raw);fallback=fallback||a.fallback;engineName=a.engine_name;
     const best=a.candidates[0],actual=a.selected,loss=CoChillEngine.difference(best,actual);
     if(!best||!actual||loss===null||loss<80||best.move===m.move)continue;
     const skill=inferSkill(pos,m.move),alternatives=a.candidates.filter(x=>CoChillEngine.difference(best,x)!==null&&CoChillEngine.difference(best,x)<=35).map(x=>x.move);
     let pvPos=pos;const line=best.pv.map(v=>{const description=XQ.describe(pvPos,v);pvPos=pvPos.play(v);return description;}).join('; sau đó ');
     found.push({id:g.id+'-p'+m.ply,title:'Vị trí ở nửa nước '+(m.ply+1),fen:pos.fen(),solution:best.move,alternatives,skill,source:a.fallback?'game-local':'game-engine',gameId:g.id,ply:m.ply,loss,
       what:`Trong ván bạn đi ${XQ.describe(pos,m.move)}. ${a.fallback?'Tìm kiếm cơ bản gợi ý':'Kết quả tìm kiếm đề xuất'} một phương án để đối chiếu; chưa phải phán quyết chắc chắn về tư duy.`,
       why:`Biến hợp lệ được tính: ${line}. Chênh lệch ${Math.round(loss)} điểm ${a.fallback?'quy ước tìm kiếm nông':'centipawn của engine'} từ cùng thế và cùng bên đi.`,
       how:HOW[skill],engine:{name:a.engine_name,fallback:a.fallback,depth:a.search?.depth,scoreType:best.score_type},pv:best.pv});
     await new Promise(r=>setTimeout(r,0));
   }
   if(analysisTask!==task||task.controller.signal.aborted)return;
   g.moments=found.sort((a,b)=>a.ply-b.ply);
   g.analysis={at:Date.now(),mode:analysisMode,positions:turns.length,fallback,engineName,limited:turns.length<g.moves.length};save();
 }catch(error){if(!task.controller.signal.aborted)toast(error.message||'Chưa phân tích được. Biên bản ván được giữ.');}
 finally{if(analysisTask===task){analysisTask=null;busy=false;render();}}
}
function moments(g){
 if(!g)return empty('Chưa có ván để xem lại','Chơi hoặc nhập một ván trước.','play','Mở trang chơi');
 if(!g.status.over)return empty('Ván đang diễn ra','Kết thúc ván rồi mở phần phân tích.','game/'+g.id,'Tiếp tục ván');
 return `${heading('Những điểm đáng nhìn lại','Chọn một hình để tự đánh giá trước khi xem phương án.','mistakes')}<p class="notice">${g.analysis?`${esc(g.analysis.engineName)} · đã kiểm tra ${g.analysis.positions} vị trí · ${g.analysis.mode==='deep'?'lượt phân tích kỹ hơn':'lượt phân tích nhanh'}. ${g.analysis.fallback?'Đang dùng máy cơ bản; gợi ý cần được đối chiếu.':''}`:'Kiểm tra tối đa 20 lượt gần nhất của bên bạn chọn. Số vị trí được đề xuất phụ thuộc bằng chứng; không ép mỗi ván phải có ba lỗi.'}</p>${busy?`<section class="panel empty"><span class="spinner"></span><p id="analysis-progress">${esc(analysisProgress)}</p>${btn('Hủy lượt phân tích','cancel-analysis','','secondary')}</section>`:g.moments?g.moments.length?'<div class="list">'+g.moments.map((p,i)=>`<div class="list-row"><div class="row-main"><span class="mini-icon">${i+1}</span><div><h3>${esc(p.title)}</h3><p>${state.records[p.id]?.pendingReview?'Cần học tiếp':state.records[p.id]?.completedAt?'Đã luyện · '+date(state.records[p.id].completedAt):'Tự quan sát trước khi xem phân tích'}</p></div></div>${btn('Suy nghĩ ở đây →','start',p.id,'secondary')}</div>`).join('')+'</div>':empty('Chưa có điểm cần sửa đủ rõ trong lượt tìm kiếm này','Bạn có thể viết ghi chú, chọn bài khác hoặc yêu cầu phân tích kỹ hơn. Kết quả này chưa chứng minh toàn ván hoàn hảo.'):`<section class="panel empty">${btn('Tìm điểm cần học →','analyze',g.id)}</section>`}<div class="button-row">${!busy&&g.moments?btn('Phân tích kỹ hơn','analyze-deep',g.id,'secondary'):''}<a class="secondary" href="#replay/${g.id}">Xem lại toàn ván</a><a class="quiet" href="#lessons">Chọn bài học khác</a></div>`;
}
function replay(g){if(!g)return empty('Không tìm thấy ván','Mở lại từ danh sách ván.','mistakes');replayIndex=Math.max(0,Math.min(replayIndex,g.moves.length));const fen=replayIndex?g.moves[replayIndex-1].after:g.initialFen;return `${heading('Xem lại toàn ván','Chế độ xem tự do. Khi luyện một điểm, các nước sau sẽ được giấu.','moments/'+g.id)}<div class="learn-grid"><div class="board-panel">${boardHTML(XQ.Position.fromFen(fen),{last:replayIndex?g.moves[replayIndex-1].move:null})}<div class="button-row">${btn('← Trước','replay-prev',g.id,'secondary')}<span class="pill">${replayIndex} / ${g.moves.length}</span>${btn('Sau →','replay-next',g.id,'secondary')}</div></div><div class="panel"><h3>${esc(g.title)}</h3><p>${replayIndex?esc(XQ.describe(XQ.Position.fromFen(g.moves[replayIndex-1].before),g.moves[replayIndex-1].move)):'Thế cờ ban đầu'}</p>${notationTable(g,true)}<div class="button-row"><a class="primary" href="#moments/${g.id}">Chọn điểm để học →</a>${btn('Xuất biên bản','export-game',g.id,'secondary')}${btn('Xóa ván','delete-game',g.id,'danger')}</div></div></div>`;}
function mistakes(){return heading('Ván của tôi','Ván cá nhân và những vị trí bạn muốn hiểu rõ hơn.')+(state.games.length?gameList():empty('Bắt đầu từ một ván của bạn','Sau ván, hệ thống gợi ý những điểm để nhìn lại.','play','Chơi hoặc nhập ván'))+`<p class="subtle separation">“Ôn tập” là lịch luyện đến hạn; khu vực này là nơi tìm lại các ván. Hai nơi dùng chung kết quả học.</p>`;}
function reviews(){
 const rows=Object.values(state.records).filter(r=>CC.reviewDueAt(r)).sort((a,b)=>Date.parse(CC.reviewDueAt(a))-Date.parse(CC.reviewDueAt(b))),s=state.session;
 return `${heading('Ôn tập','Học tiếp phần chưa hiểu, rồi ôn những hình đã hoàn thành. Giờ Việt Nam · UTC+7.')}${s&&!['summary','parked'].includes(s.stage)?`<div class="next-up"><div><strong>Bài đang dở vẫn được giữ</strong><p>Tiếp tục đúng bước và câu trả lời.</p></div>${btn('Tiếp tục →','resume')}</div>`:''}${['game','lesson'].map(group=>{const entries=rows.filter(r=>{const p=findPuzzle(r.puzzleId);return p&&(group==='game'?!!p.gameId:!p.gameId);});return `<section class="panel separation"><h2>${group==='game'?'Từ ván của bạn':'Từ bài học'}</h2>${entries.length?entries.map(r=>{const p=findPuzzle(r.puzzleId),due=CC.reviewDueAt(r),late=Date.parse(due)<=Date.now();return `<div class="list-row"><div><h3>${esc(p.title)}</h3><p class="${late?'due-now':''}">${r.pendingReview?'Cần học tiếp · chưa hoàn thành':'Ôn hình đã học'} · ${late?'Đến hạn':'Hẹn '+date(due)}</p></div>${btn(r.pendingReview?'Học tiếp':'Ôn lại','start-review',p.id,'secondary')}</div>`;}).join(''):'<p>Chưa có hình trong hàng đợi này.</p>'}</section>`;}).join('')}<p class="notice separation">Lịch hoàn thành: 1 / 2 / 7 / 14 / 30 ngày theo kết quả. Hình chưa giải được được hẹn học tiếp ngày sau, không tính là hoàn thành. Tự đánh giá không thay đổi lịch.</p>`;
}
function summary(){if(!state.session)return empty('Chưa có phiên học','Hãy chọn một bài để bắt đầu.');return `${heading('Khép lại một phiên học','Ghi một điều nhỏ để lần sau biết mình cần tiếp tục ở đâu.')}<section class="panel summary-box"><span class="summary-icon">✓</span><h2>Hôm nay bạn mang theo điều gì?</h2><form id="summary-form">${['Tôi đã quan sát trước khi chọn nước','Tôi hiểu thêm lý do của một nước đi','Tôi đã thử một hình cùng chủ đề','Tôi còn điều chưa chắc và muốn ôn lại'].map((x,i)=>`<label class="check-line"><input type="checkbox" name="check" value="${i}" ${(state.session.summaryChecks||[]).includes(String(i))?'checked':''}><span>${x}</span></label>`).join('')}<label class="field"><span>Một điều bạn muốn nhớ</span><textarea name="note" maxlength="1500" rows="3" placeholder="Lần sau tôi sẽ kiểm tra…">${esc(state.session.summaryNote||'')}</textarea></label><p class="notice">Đây là tự đánh giá. Các ô tích không tự tăng trình độ hoặc thay đổi lịch ôn. Mỗi hình đã có lịch riêng từ lúc hoàn thành.</p><button class="primary" type="submit">Lưu & trở về trang chủ →</button><a class="quiet" href="#home">Bỏ qua tự đánh giá · kết quả học vẫn được giữ</a></form></section>`;}

function profile(){const records=completed(),stats=CC.evidence(state.records);return `${heading('Tiến độ của bạn','Chỉ ghi nhận hoạt động thực tế trên trình duyệt này.')}<div class="stat-grid"><div class="stat"><b>${stats.count}</b><span>lượt luyện đã ghi nhận</span></div><div class="stat"><b>${dueRecords().length}</b><span>hình đến hạn ôn</span></div><div class="stat"><b>${stats.firstEligible?Math.round(stats.firstCorrect/stats.firstCount*100)+'%':'—'}</b><span>${stats.firstEligible?`nước đầu phù hợp mẫu, không hỗ trợ · ${stats.firstCorrect}/${stats.firstCount} bài`:'Chưa đủ dữ liệu · cần 6 bài khác nhau để hiện tỷ lệ'}</span></div></div><p class="notice">EXP hoạt động: ${stats.independent*10+stats.assisted*3} · điểm động viên theo lượt luyện, không phải Elo hoặc trình độ. Trình độ tự chọn: ${prefs.level==='new'?'Chưa biết chơi':prefs.level==='beginner'?'Mới biết luật':'Đã biết chơi'}. Đây không phải kết quả đánh giá đầu vào hoặc xếp hạng thi đấu.</p><div class="grid-2"><section class="panel"><h3>Bằng chứng theo kỹ năng</h3>${Object.entries(SKILLS).map(([k,n])=>{const e=CC.evidence(state.records,k);return `<div class="skill-row"><h4>${n}</h4><p>${e.eligible?`${e.count} lượt · ${e.independent} lượt chọn nước phù hợp không hỗ trợ · ${e.assisted} lượt có hỗ trợ`:`Chưa đủ dữ liệu (${e.count}/6 lượt). Chưa hiện biểu đồ hoặc điểm kỹ năng.`}</p>${e.eligible?`<progress max="${e.count}" value="${e.independent}" aria-label="Lượt chọn nước phù hợp không hỗ trợ"></progress>`:''}</div>`;}).join('')}<p class="subtle">Kết quả nước đi không chứng minh chất lượng lý giải hoặc mức thành thạo.</p><a class="secondary" href="#review">Đến lịch ôn →</a></section><section class="panel"><h3>Góc cá nhân</h3><form id="profile-form"><label class="field"><span>Tên hiển thị</span><input type="text" name="name" maxlength="40" value="${esc(state.profile.name)}" placeholder="Bạn muốn được gọi là gì?"></label><button class="secondary" type="submit">Lưu tên</button></form><p class="subtle separation">Khách lưu trên máy. Đăng nhập để đồng bộ tiến độ giữa các thiết bị.</p><a class="primary" href="#account">Tài khoản & đồng bộ →</a><a class="secondary" href="#settings">Giao diện và dữ liệu →</a></section></div><section class="panel separation"><h3>Những lần tự nhìn lại</h3>${state.summaries.length?state.summaries.slice(-5).reverse().map(item=>`<div class="explanation-section"><h4>${date(item.at)}</h4><p>${esc(item.note||'Đã lưu tự đánh giá.')} (${item.checks.length} mục)</p></div>`).join(''):'<p>Chưa có tự đánh giá. Sau phiên học, bạn có thể ghi một điều muốn nhớ.</p>'}</section>`;}
function about(){return `${heading('Về Cờ Chill','Bản V5 · chơi, suy nghĩ, vận dụng và trở lại.')}<article class="article"><h2>Vòng học đang hoạt động</h2><p>Chơi với máy hoặc hai người một thiết bị, nhập biên bản từ đầu ván, chọn điểm cần xem lại, tự nêu nhận định và một nước, đối chiếu lời giải, thử lại, luyện một hình liên quan và ôn theo lịch. Ba lượt chưa tìm ra được giữ là cần học tiếp.</p><h2>Tài khoản và quản trị</h2><p>Khi chạy cùng máy chủ Cờ Chill, bạn có thể đăng ký, đăng nhập, đồng bộ giữa thiết bị, xuất và xóa dữ liệu. Chủ website có thống kê, phản hồi và công cụ biên tập. Bản chỉ có giao diện tĩnh vẫn dùng chế độ khách.</p><h2>Phân tích có căn cứ</h2><p>Luật kiểm tra nước đi. Bộ kết nối Pikafish chỉ hoạt động khi người vận hành cài engine và trọng số phù hợp; chưa có sẵn trong mã nguồn. Khi dùng tìm kiếm cơ bản, giao diện ghi rõ giới hạn. Mọi chuỗi được phát lại qua luật; điểm vật chất tìm kiếm nông không chứng minh một sai lầm chiến lược.</p><h2>Giới hạn hiện tại</h2><p>Lời giải theo mẫu, chưa có LLM chấm lập luận, AI tự huấn luyện, Elo được kiểm định, PvP online hoặc giáo trình lớn đã duyệt. 12 hình mẫu tự dựng dùng để thử vòng học. Bộ luật giải đấu Việt Nam và các chuỗi chiếu/đuổi phức tạp chưa được xác minh đầy đủ.</p><div class="button-row"><a class="primary" href="#help">Trợ giúp & phản hồi</a><a class="secondary" href="#privacy">Cách sử dụng dữ liệu</a></div></article>`;}
function applyPreferences(){document.documentElement.dataset.theme=prefs.theme;document.documentElement.dataset.font=prefs.font;document.body.classList.toggle('sidebar-collapsed',prefs.sidebar);$('sidebar-toggle')?.setAttribute('aria-expanded',String(!prefs.sidebar));$('sound-toggle')?.setAttribute('aria-pressed',String(prefs.sound));if($('sound-toggle'))$('sound-toggle').textContent=prefs.sound?'♪ Âm thanh bật':'♪ Âm thanh tắt';try{localStorage.setItem(PREF_KEY,JSON.stringify(prefs));}catch{toast('Không lưu được tùy chọn trên thiết bị.');}}
function playSound(kind){if(!prefs.sound)return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime,o=audioContext.createOscillator(),gain=audioContext.createGain();o.type='sine';o.frequency.setValueAtTime(({move:420,capture:220,check:660,success:880,error:160})[kind]||420,now);gain.gain.setValueAtTime(0.001,now);gain.gain.exponentialRampToValueAtTime(.06,now+.02);gain.gain.exponentialRampToValueAtTime(.001,now+.2);o.connect(gain);gain.connect(audioContext.destination);o.start();o.stop(now+.22);}catch{/* Sound is optional; gameplay remains available. */}}
function settings(){const select=(key,label,options)=>`<label class="field"><span>${label}</span><select name="${key}" aria-label="${label}">${options.map(([v,t])=>`<option value="${v}" ${prefs[key]===v?'selected':''}>${t}</option>`).join('')}</select></label>`;return `${heading('Cài đặt','Chọn cách hiển thị thoải mái cho bạn.')}<div class="settings-grid grid-2"><section class="panel"><h3>Giao diện và bàn cờ</h3><form id="settings-form">${select('theme','Chủ đề',[['warm','Sáng ấm'],['cool','Trắng lạnh'],['dark','Tối']])}${select('pieces','Tên quân',[['han','Chữ Hán'],['vi','Tiếng Việt']])}${select('font','Cỡ chữ',[['normal','Dễ đọc'],['large','Lớn hơn']])}${select('level','Mức tự chọn',[['new','Chưa biết chơi'],['beginner','Mới biết luật'],['intermediate','Đã biết chơi']])}${select('tone','Giọng hướng dẫn',[['neutral','Trung tính'],['friendly','Bạn học cùng']])}<label class="check-line"><input type="checkbox" name="sound" ${prefs.sound?'checked':''}> Bật âm thanh nhẹ</label><button class="primary" type="submit">Lưu tùy chọn</button></form><p class="subtle separation">Âm thanh được tổng hợp trên thiết bị. Không sử dụng âm thanh từ ứng dụng khác.</p></section><section class="panel"><h3>Dữ liệu và quyền riêng tư</h3><p>Khách lưu trên trình duyệt. Khi đăng nhập, tiến độ được đồng bộ vào tài khoản; xem trạng thái lưu ở đầu trang.</p><a class="secondary" href="#account">Tài khoản, xuất và xóa dữ liệu</a><p>Không gửi ván hoặc câu trả lời để huấn luyện. Bản xuất không chứa đáp án ẩn của bài tập.</p><div class="button-row">${btn('Xuất dữ liệu cá nhân','export','','secondary')}${btn('Xóa lịch sử học và lịch ôn','delete-learning','','danger')}${btn('Xóa toàn bộ dữ liệu','delete','','danger')}</div><p class="subtle separation">File xuất là bản sao để đọc; chưa có nhập phục hồi tự động. Xóa dữ liệu không thể hoàn tác.</p><a href="#profile" class="secondary">Quay về hồ sơ →</a></section></div>`;}
function howto(){return `${heading('Bắt đầu với Cờ Chill','Một ván cờ, một điều hiểu rõ hơn.')}<div class="grid-2"><section class="panel"><h2>Bạn đang ở đâu?</h2><p>Chọn để điều chỉnh mức gợi mở. Đây là thông tin tự khai, chưa phải bài kiểm tra xếp hạng.</p><div class="button-row">${btn('Tôi chưa biết chơi','onboard','new','secondary')}${btn('Tôi mới biết luật','onboard','beginner','secondary')}${btn('Tôi đã biết chơi','onboard','intermediate','secondary')}</div><p class="subtle separation">Không cần nhập tuổi hoặc thông tin liên hệ để thử. Bản này lưu trên cùng trình duyệt.</p></section><section class="panel"><h3>Cách thao tác</h3><ol><li>Bấm một quân, rồi bấm ô muốn đi. Bấm lại quân đó để hủy chọn.</li><li>Sau ván, chọn một vị trí cần xem lại.</li><li>Viết suy nghĩ và chọn nước trước khi xem hướng dẫn.</li><li>Thử thêm một bài, rồi xem lịch ôn và ghi điều đã học.</li></ol><p>Nếu chưa tìm ra, dùng “Tôi chưa biết” để nhận câu hỏi quan sát nhỏ hơn.</p><div class="button-row">${btn('Thử một bài mẫu →','start',puzzleBank()[0].id)}<a class="secondary" href="#play">Bỏ qua hướng dẫn · chơi cờ</a></div></section></div><p class="notice separation">Bài mẫu tự dựng, không phải ván của người dùng thật. Video hướng dẫn sẽ bổ sung sau; bản này có hướng dẫn chữ và bàn cờ tương tác.</p>`;}
function learningPath(){const stages=[['01','Nắm luật đi quân','Nhận ra đường đi và những điều kiện bị cản.','rules','Xem luật'],['02','Quan sát một hình cờ','Tự nêu ý trước khi xem hướng dẫn.','lessons','Chọn bài'],['03','Chơi và nhìn lại','Tìm một quyết định đáng học từ ván của bạn.','play','Chơi cờ'],['04','Vận dụng và ôn lại','Làm thêm bài rồi trở lại đúng lịch đã hẹn.','review','Mở lịch ôn']];return `${heading('Hành trình học','Bốn bước có thể quay lại bất cứ lúc nào.')}<div class="learning-path">${stages.map(([n,t,d,url,cta])=>`<article class="path-node panel"><span class="mini-icon">${n}</span><div><h2>${t}</h2><p>${d}</p><a class="secondary" href="#${url}">${cta} →</a></div></article>`).join('')}</div><p class="notice separation">Lộ trình gợi ý, chưa phải giáo trình phân cấp hoặc bài đánh giá đầu vào đã được kiểm chứng. Không khóa bài theo điểm kinh nghiệm giả.</p>`;}
function rulesPage(){const rules=[['Tướng','Đi thẳng hoặc ngang một ô trong cung. Hai Tướng không được nhìn thẳng nhau trên cùng cột khi không có quân chắn.'],['Sĩ','Đi chéo một ô và luôn ở trong cung.'],['Tượng','Đi chéo hai ô, không qua sông. Ô giữa đường chéo là mắt Tượng; có quân ở đó thì không đi được.'],['Mã','Đi một ô thẳng rồi một ô chéo ra ngoài. Ô thẳng đầu tiên là chân Mã; bị chặn thì không đi được hướng đó.'],['Xe','Đi thẳng hoặc ngang qua các ô trống; không nhảy qua quân.'],['Pháo','Khi không ăn quân, đi như Xe. Khi ăn quân, phải có đúng một quân nằm giữa Pháo và mục tiêu.'],['Tốt','Mỗi nước tiến một ô. Qua sông được đi ngang một ô; không bao giờ đi lùi.']];return `${heading('Luật đi quân','Tọa độ trên bàn không thay đổi khi lật góc nhìn.','howto')}<div class="grid-2">${rules.map(([n,t])=>`<section class="panel"><h3>${n}</h3><p>${t}</p></section>`).join('')}<section class="panel"><h3>An toàn Tướng và hết ván</h3><p>Không được đi nước khiến Tướng mình bị chiếu. Chiếu hết hoặc hết nước hợp lệ đều là thua. Hết giờ và xin thua được ghi riêng; thỏa thuận hòa cần hai người cùng đồng ý.</p></section></div><section class="panel separation"><h3>Lặp thế và phán quyết</h3><p>Mục tiêu sản phẩm là luật thi đấu Việt Nam. Hiện chưa có văn bản chính thức và bộ tình huống đã duyệt để xác nhận tuân thủ đầy đủ. Bộ xử lý hiện tại tham khảo WXF Rules 2018. Bản thử xử lý chuỗi chiếu một bên lặp rõ ràng; các chuỗi đuổi quân hoặc vừa chiếu vừa đuổi cần kiểm chứng. Chạm mốc lặp hoặc 100 nửa nước không ăn quân có thể dừng để xác minh; không tự suy thành hòa khi còn ngoại lệ.</p><p>Không dùng bản này làm trọng tài giải đấu. Các tình huống chưa rõ sẽ được bổ sung bằng case và nguồn luật cụ thể.</p><a class="secondary" href="https://www.wxf-xiangqi.org/images/wxf-rules/2018_World_XiangQi_Rules_English2018.pdf" target="_blank" rel="noopener">Nguồn WXF</a></section><div class="button-row">${state.session?btn('Trở lại bài đang học','resume'):btn('Thực hành một hình','start',puzzleBank()[0].id)}<a class="quiet" href="#howto">Quay lại cách học</a></div>`;}
function render(){if(booting){$('main').innerHTML='<section class="panel empty"><p>Đang mở Cờ Chill và kiểm tra phiên đăng nhập…</p></section>';return;}const [page,id]=route();let content;try{if(activeGame()&&['learn','opening','moments','replay','lessons','rules'].includes(page)){content=empty('Ván đang diễn ra','Hãy kết thúc ván trước khi mở hướng dẫn hoặc xem lại.','game/'+activeGame().id,'Tiếp tục ván');}else switch(page){case'play':content=playSetup();break;case'lessons':content=lessons();break;case'learn':content=learn();break;case'opening':content=opening(Number(id));break;case'game':content=gameView(state.games.find(g=>g.id===id));break;case'moments':content=moments(state.games.find(g=>g.id===id));break;case'replay':content=replay(state.games.find(g=>g.id===id));break;case'mistakes':content=mistakes();break;case'review':content=reviews();break;case'summary':content=summary();break;case'profile':content=profile();break;case'about':content=about();break;case'account':content=window.CCCloudUI?.account()||empty('Đang kết nối tài khoản','Vui lòng đợi một chút.');break;case'admin':content=window.CCCloudUI?.admin()||'';break;case'editor':content=window.CCCloudUI?.editor()||'';break;case'help':content=window.CCCloudUI?.help()||'';break;case'privacy':content=window.CCCloudUI?.privacy()||'';break;case'settings':content=settings();break;case'howto':content=howto();break;case'path':content=learningPath();break;case'rules':content=rulesPage();break;default:content=home();}}catch(e){content=empty('Không mở được dữ liệu này','Dữ liệu cũ vẫn được giữ. Bạn có thể xuất bản sao trong hồ sơ.','settings','Mở dữ liệu');console.error(e);} $('main').innerHTML=content;$('avatar').textContent=(state.profile.name||'C').slice(0,1).toUpperCase();document.querySelectorAll('.desktop-nav a,.mobile-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));document.title=(document.querySelector('#main h1')?.textContent||'Trang chủ')+' · Cờ Chill';applyPreferences();window.CCCloudUI?.refreshChrome();}
function invalidMove(g,pos,move){const message=CC.illegalMoveReason(pos,move);if(g){g.invalidMoves=(g.invalidMoves||[]).concat({at:Date.now(),move,reason:message}).slice(-100);save();}const box=$('game-feedback')||$('move-feedback');if(box)box.textContent=message;playSound('error');toast(message);}
function selectSquare(sq){if(booting)return;const [page,id]=route();if(page==='game'){const g=state.games.find(x=>x.id===id);if(!g||g.status.over||g.technicalPause||busy)return;const pos=XQ.Position.fromFen(g.fen);if(g.mode==='bot'&&pos.turn!==g.player)return;const piece=pos.board[XQ.index(sq)];if(piece!=='.'&&XQ.side(piece)===pos.turn){selected=selected===sq?null:sq;return render();}if(!selected)return toast('Chọn quân của bên đến lượt trước.');const move=selected+sq;if(!pos.legalMoves().includes(move))return invalidMove(g,pos,move);return moveGame(g,move);}
 if(page!=='learn'||!state.session)return;const session=state.session,p=currentPuzzle();if(!['reflect','retry'].includes(session.stage))return;const pos=XQ.Position.fromFen(p.fen),piece=pos.board[XQ.index(sq)];if(piece!=='.'&&XQ.side(piece)===pos.turn){selected=selected===sq?null:sq;session.selected=selected;save();return render();}if(!selected)return toast('Chọn quân của bên đến lượt trước.');const move=selected+sq;if(!pos.legalMoves().includes(move))return invalidMove(null,pos,move);selected=null;session.selected=null;if(session.stage==='retry'){session.retryCount=(session.retryCount||0)+1;if(accepted(p,move)){toast('Bạn đã đi lại được phương án. Lần đầu và lần luyện lại được ghi riêng.');playSound('success');session.stage='explain';}else if(session.retryCount>=3){session.stage='explain';toast('Đã thử ba lượt. Hãy đối chiếu ý tưởng và đưa hình này vào ôn tập.');}else{toast('Nước hợp lệ nhưng chưa khớp mục tiêu mẫu. Kiểm tra phản ứng của đối phương.');playSound('error');}}else session.candidate=move;save();render();}
function download(name,contents,type='application/json'){const url=URL.createObjectURL(new Blob([contents],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
document.addEventListener('click',e=>{const square=e.target.closest('[data-square]');if(square)return selectSquare(square.dataset.square);const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,v=el.dataset.value;try{switch(a){
 case'toggle-sidebar':prefs.sidebar=!prefs.sidebar;applyPreferences();break;
 case'toggle-sound':prefs.sound=!prefs.sound;applyPreferences();playSound('move');break;
 case'toggle-pieces':prefs.pieces=prefs.pieces==='han'?'vi':'han';render();break;
 case'flip-board':boardFlipped=!boardFlipped;render();break;
 case'onboard':prefs.level=v;applyPreferences();go(v==='new'?'rules':'lessons');break;
 case'start':beginPuzzle(findPuzzle(v),{source:v.startsWith('g')?'game':'lesson'});break;
 case'start-review':if(state.records[v]?.pendingReview){if(activeGame())return toast('Kết thúc ván trước khi học.');state=CC.resumeParked(state,v);selected=null;save();go('learn');}else beginPuzzle(findPuzzle(v),{source:'review'});break;
 case'resume':selected=state.session?.selected||null;showVariation=false;go('learn');break;
 case'pause':if(!confirm('Lưu chỗ đang học và về trang chủ? Bạn có thể tiếp tục sau.'))break;save();go('home');toast('Đã giữ chỗ và câu trả lời trên trình duyệt này.');break;
 case'unknown':{const session=state.session;if(!session||session.stage!=='reflect')break;session.assisted=true;session.helpLevel=Math.min(3,(session.helpLevel||0)+1);if(!session.helpReadyAt)session.helpReadyAt=Date.now();save();render();break;}
 case'guided-reveal':{const session=state.session;if(!session||session.stage!=='reflect'||!session.helpLevel||Date.now()<session.helpReadyAt)break;session.unknown=true;state.session=CC.reveal(session);selected=null;showVariation=false;save();render();break;}
 case'retry':if((state.session.retryCount||0)>=3){toast('Bạn đã dùng ba lượt thử lại. Hãy kết thúc lượt học để hẹn ôn.');break;}state.session.stage='retry';showVariation=false;selected=null;save();render();break;
 case'explain':state.session.stage='explain';save();render();break;
 case'variation':showVariation=!showVariation;render();break;
 case'marks':showMarks=!showMarks;render();break;
 case'finish':playSound('success');finish();break;
 case'next-related':nextRelated();break;
 case'related-start':beginPuzzle(findPuzzle(state.session.pendingPuzzleId),{related:true,source:'related',force:true});break;
 case'summary':go('summary');break;
 case'phase':lessonPhase=v;render();break;
 case'opening':replayIndex=0;go('opening/'+v);break;
 case'opening-before':replayIndex=0;render();break;
 case'opening-after':replayIndex=1;render();break;
 case'mode':mode=v;render();break;
 case'analyze':analyzeGame(state.games.find(g=>g.id===v));break;case'analyze-deep':analyzeGame(state.games.find(g=>g.id===v),'deep');break;case'cancel-analysis':analysisTask?.controller.abort();analysisTask=null;busy=false;render();toast('Đã hủy lượt phân tích; biên bản ván vẫn được giữ.');break;

 case'resign':{const g=state.games.find(x=>x.id===v);if(!g||g.status.over||!confirm('Xin thua và kết thúc ván này?'))break;g.status={over:true,winner:XQ.other(g.mode==='bot'?g.player:XQ.Position.fromFen(g.fen).turn),reason:'Xin thua'};save();render();break;}
 case'draw':{const g=state.games.find(x=>x.id===v);if(!g||g.status.over||g.mode!=='local')break;g.drawOffer={from:XQ.Position.fromFen(g.fen).turn,expiresAt:Date.now()+15000};save();render();break;}
 case'draw-accept':case'draw-decline':{const g=state.games.find(x=>x.id===v);if(!g?.drawOffer||g.status.over)break;if(a==='draw-accept'&&g.drawOffer.expiresAt>Date.now()&&!tickGame(g))g.status={over:true,winner:null,reason:'Hai bên đồng ý hòa'};delete g.drawOffer;save();render();break;}
 case'retry-bot':{const g=state.games.find(x=>x.id===v);g.technicalPause=false;g.clock.last=Date.now();save();maybeBot(g);break;}case'technical-end':{const g=state.games.find(x=>x.id===v);g.technicalPause=false;g.status={over:true,winner:null,reason:'Kết thúc do sự cố kỹ thuật',technical:true};save();render();break;}case'rematch':{const g=state.games.find(x=>x.id===v);mode=g.mode==='local'?'local':'bot';newGame({color:'random',depth:g.depth,seconds:g.clock?.enabled?600:0,increment:g.clock?.enabled?5:0});break;}
 case'replay-prev':replayIndex--;render();break;
 case'replay-next':replayIndex++;render();break;
 case'replay-jump':replayIndex=Number(v);render();break;
 case'library-filter':libraryFilter=v;libraryPage=0;render();break;
 case'library-prev':libraryPage=Math.max(0,libraryPage-1);render();break;
 case'library-next':libraryPage++;render();break;
 case'favorite':{const g=state.games.find(x=>x.id===v);g.favorite=!g.favorite;save();render();break;}
 case'export-game':{const g=state.games.find(x=>x.id===v);const text=CC.pairMoveHistory(g.initialFen,g.moves).map(r=>`${r.number}. ${r.red?.notation||'...'} ${r.black?.notation||''}`).join('\n');download('co-chill-bien-ban.txt',`FEN: ${g.initialFen}\n\n${text}`,'text/plain');break;}
 case'delete-game':{const g=state.games.find(x=>x.id===v);if(!g?.status.over)break;if(!confirm('Xóa ván này và các lượt luyện/lịch ôn trực tiếp từ ván này trên trình duyệt? Bài trong thư viện và ghi chú tự đánh giá khác được giữ.'))break;state.games=state.games.filter(x=>x.id!==v);for(const id of Object.keys(state.records))if(id.startsWith(v+'-p'))delete state.records[id];if(state.session?.puzzleId.startsWith(v+'-p'))state.session=null;save();go('mistakes');break;}
 case'export':download('co-chill-du-lieu-ca-nhan.json',JSON.stringify(CC.safeExport(state),null,2));toast('Đã tạo bản xuất không kèm đáp án ẩn.');break;
 case'delete-learning':if(confirm('Xóa câu trả lời, lượt luyện, lịch ôn và tự đánh giá trên trình duyệt này? Các ván cờ được giữ.')){state.records={};state.session=null;state.summaries=[];save();render();toast('Đã xóa dữ liệu học.');}break;
 case'delete':if(confirm('Xóa toàn bộ ván, câu trả lời, lịch ôn, hồ sơ và cài đặt trên trình duyệt này? Hãy xuất dữ liệu trước nếu cần.')){localStorage.removeItem(KEY);localStorage.removeItem(PREF_KEY);state=CC.fresh();prefs=CC.preferences();selected=null;save();render();toast('Đã xóa toàn bộ dữ liệu của bản này.');}break;
 }}catch(err){toast(err.message||'Chưa thực hiện được. Dữ liệu được giữ lại.');}});
document.addEventListener('input',e=>{if(e.target.dataset.answer!==undefined&&state.session){state.session.answers[Number(e.target.dataset.answer)]=e.target.value;save();if($('draft-status'))$('draft-status').textContent=storageOK?'Đã lưu trên trình duyệt này':'Chưa lưu được · hãy sao chép câu trả lời';}if(e.target.closest('#summary-form')&&state.session){const form=e.target.closest('form');state.session.summaryNote=form.elements.note.value;state.session.summaryChecks=[...form.querySelectorAll('[name=check]:checked')].map(x=>x.value);save();}});
document.addEventListener('change',async e=>{if(e.target.id!=='notation-file')return;const file=e.target.files?.[0];if(!file)return;if(file.size>50000)return toast('File quá lớn. Bản thử nhận tối đa 50 KB văn bản.');const text=await file.text(),fen=text.match(/^FEN:\s*(.+)$/m);if(fen)e.target.form.elements.fen.value=fen[1].trim();e.target.form.elements.moves.value=text.replace(/^FEN:.*$/m,'').trim();});
document.addEventListener('submit',e=>{if(!['reflection-form','new-game-form','import-form','summary-form','profile-form','settings-form'].includes(e.target.id))return;e.preventDefault();const data=new FormData(e.target);try{switch(e.target.id){
 case'reflection-form':{const session=state.session,p=currentPuzzle(),check=CC.reflectionCheck(session,p);if(!check.ready){const message=check.missing.length?'Hãy viết suy nghĩ ở cả ba câu. Có thể dùng gợi ý nếu bạn chưa biết.':'Chọn một nước trên bàn trước khi gửi.';$('learn-feedback').textContent=message;document.querySelector(check.missing.length?`[data-answer="${check.missing[0]}"]`:'[data-square]')?.focus();return;}if(!session.firstAnswers){session.firstAnswers=session.answers.slice();session.firstCandidate=session.candidate;}session.submissionCount=check.attempts;session.assisted=check.assisted;if(check.park){state=CC.parkPuzzle(state,session,p);selected=null;toast('Đã giữ bài chưa hoàn thành để thử lại ngày mai. Bạn có thể chuyển sang một hình dễ hơn.');}else if(check.reveal){state.session=CC.reveal(session);selected=null;showVariation=false;}else{session.helpLevel=Math.max(1,session.helpLevel||0);if(!session.helpReadyAt)session.helpReadyAt=Date.now();session.coachFeedback='Nước này hợp lệ nhưng chưa khớp mục tiêu mẫu. Bạn thử kiểm tra Tướng, đường quân và phản ứng đối thủ một lần nữa. Câu tự luận chưa được tự động chấm.';playSound('error');}save();render();break;}
 case'new-game-form':{const [seconds,increment]=String(data.get('time')).split('+').map(Number);newGame({color:data.get('color'),seconds,increment,depth:Number(data.get('depth')||1),engineChoice:String(data.get('engine')||'local')});break;}
 case'import-form':{if(activeGame())return toast('Kết thúc ván đang chơi trước khi nhập để học.');const fen=String(data.get('fen')).trim()||XQ.START_FEN,parsed=CC.parseGameNotation(fen,String(data.get('moves')||''),200);if(XQ.Position.fromFen(fen).fen()!==XQ.Position.fromFen(XQ.START_FEN).fen()||!parsed.moves.length)throw new Error('Nhập ván cần biên bản từ thế xuất phát. FEN đơn lẻ chưa được coi là một ván đầy đủ.');if(!data.has('completeRecord'))throw new Error('Xác nhận bạn đã nhập đủ biên bản từ đầu đến cuối.');newGame({fen,moves:parsed.moves,imported:true,color:String(data.get('reviewSide'))});break;}
 case'summary-form':state=CC.summarizeSession(state,{checks:data.getAll('check'),note:data.get('note')});state.session.stage='summary';save();go('home');toast('Đã lưu tự đánh giá. Lịch ôn của từng hình được giữ riêng.');break;
 case'profile-form':state.profile.name=String(data.get('name')).trim().slice(0,40);save();render();toast('Đã lưu tên trên thiết bị.');break;
 case'settings-form':prefs=CC.preferences({...Object.fromEntries(data.entries()),sound:data.has('sound'),sidebar:prefs.sidebar});save();render();toast('Đã lưu giao diện; đăng nhập sẽ đồng bộ tùy chọn.');break;
 }}catch(err){const box=$('import-feedback')||$('learn-feedback');if(box)box.textContent=err.message;else toast(err.message);}});
document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key==='Enter'&&e.target.closest('#reflection-form')){e.preventDefault();$('reflection-form').requestSubmit();return;}const button=e.target.closest('[data-square]');if(!button)return;if(e.key==='Escape'){selected=null;render();return;}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const i=XQ.index(button.dataset.square),step=({ArrowLeft:-1,ArrowRight:1,ArrowUp:-9,ArrowDown:9}[e.key])*(boardFlipped?-1:1),j=i+step;if(j>=0&&j<90&&(Math.abs(step)===9||Math.floor(i/9)===Math.floor(j/9)))document.querySelector(`[data-square="${XQ.square(j)}"]`)?.focus();});
let internalNavigation=false,restoringNavigation=false;
let analysisTask=null;
function guardedNavigation(){if(restoringNavigation){restoringNavigation=false;return;}const before=previousRoute.slice(1).split('/')[0],after=route()[0],leaving=before!==after&&((before==='game'&&activeGame())||(before==='learn'&&state.session?.stage==='reflect'));if(analysisTask&&location.hash!==analysisTask.route){analysisTask.controller.abort();analysisTask=null;busy=false;}if(leaving&&!internalNavigation&&!confirm(before==='game'?'Rời trang ván cờ? Ván được giữ, nhưng đồng hồ vẫn chạy.':'Rời bài đang suy nghĩ? Câu trả lời được lưu để tiếp tục sau.')){restoringNavigation=true;location.hash=previousRoute;return;}internalNavigation=false;previousRoute=location.hash;selected=null;render();window.scrollTo(0,0);$('main').focus({preventScroll:true});const [page,id]=route();if(page==='game')maybeBot(state.games.find(g=>g.id===id));}
window.addEventListener('hashchange',guardedNavigation);
window.addEventListener('beforeunload',e=>{save();if(activeGame()||route()[0]==='learn'&&state.session?.stage==='reflect'){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{state=CC.sanitize(JSON.parse(e.newValue));selected=null;render();toast('Đã nhận thay đổi từ tab khác.');}catch{toast('Không đọc được thay đổi từ tab khác.');}});
setInterval(()=>{if(booting)return;const g=activeGame();if(g){if(g.drawOffer&&g.drawOffer.expiresAt<=Date.now()){delete g.drawOffer;save();if(route()[0]==='game')render();}if(tickGame(g)){if(route()[0]==='game')render();}else for(const color of ['w','b'])if($('clock-'+color))$('clock-'+color).textContent=clockText(g,color);}const help=$('guided-reveal');if(help&&state.session){const wait=Math.max(0,Math.ceil(((state.session.helpReadyAt||0)-Date.now())/1000));help.disabled=wait>0;help.textContent=wait?`Quan sát thêm ${wait} giây`:'Vẫn chưa tìm ra · xem hướng dẫn';}},300);
render();if(!booting){save();const initial=activeGame();if(initial){tickGame(initial);maybeBot(initial);}}
